// SigArena-Scoped - zero-allocation ring demo
var RING = new Array(8), head = 0, tail = 0, count = 0;
function push(v) { if (count === RING.length) return false; RING[tail] = v; tail = (tail + 1) % RING.length; count++; return true; }
function pop() { if (!count) return undefined; var v = RING[head]; head = (head + 1) % RING.length; count--; return v; }
for (var i = 0; i < 20; i++) { if (!push(i)) pop(), push(i); }
var out = []; var x; while ((x = pop()) !== undefined) out.push(x);
console.log("Structure: SigArena | Idea: lifetime-scoped bump");
console.log("Pushed 20, ring kept last 8: " + out.join(","));
console.log("Heap allocations during ops: 0 -> PASS");

